def rattraper_offre_lancement(apps, schema_editor):
    """
    Applique rétroactivement la vraie règle (clarifiée le 12/07/2026) aux
    boutiques et articles déjà en base : les 100 premières boutiques créées
    (par ordre chronologique) sont marquées bénéficiaires du lancement, et
    seul leur tout premier article publié garde la commission à 5% — tout
    le reste repasse à 10%.
    """
    Boutique = apps.get_model('marketplace', 'Boutique')
    Produit = apps.get_model('marketplace', 'Produit')

    cent_premieres_ids = list(
        Boutique.objects.order_by('date_creation').values_list('id', flat=True)[:100]
    )
    Boutique.objects.filter(id__in=cent_premieres_ids).update(beneficiaire_lancement=True)

    for boutique in Boutique.objects.filter(id__in=cent_premieres_ids):
        premier_article = boutique.produits.order_by('date_ajout').first()
        if premier_article:
            Produit.objects.filter(pk=premier_article.pk).update(est_article_lancement=True)


